  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts list_sessions with an optional non-negative integer limit and finite-date before cursor, stripping unknown fields and rejecting malformed ones', () => {
    const cursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    const expectedFrame: ListSessionsMessage = {type: 'list_sessions', limit: 10, before: cursor};
    const summaryFrame: SessionSummaryFrame = {
      sessionId: 's2',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:02:00.000Z',
      entryCount: 4,
    };
    const listFrame: SessionListMessage = {type: 'session_list', sessions: [summaryFrame]};
    const incoming: IncomingMessage = expectedFrame;
    const outgoing: OutgoingMessage = listFrame;
    const rejected = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: null},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ].map(frame => validateMessage(frame).valid);

    expect({
      bare: validateMessage({type: 'list_sessions'}),
      zeroLimit: validateMessage({type: 'list_sessions', limit: 0}),
      epochCursor: validateMessage({type: 'list_sessions', before: {updatedAt: 1700000000000, sessionId: 's1'}}),
      stripped: validateMessage({
        type: 'list_sessions',
        limit: 10,
        before: {...cursor, extra: 'ignored'},
        userId: 'u2',
      }),
      rejected,
      outgoingType: outgoing.type,
    }).toEqual({
      bare: {valid: true, data: {type: 'list_sessions'}},
      zeroLimit: {valid: true, data: {type: 'list_sessions', limit: 0}},
      epochCursor: {
        valid: true,
        data: {type: 'list_sessions', before: {updatedAt: 1700000000000, sessionId: 's1'}},
      },
      stripped: {valid: true, data: incoming},
      rejected: Array(9).fill(false),
      outgoingType: 'session_list',
    });
  });
});

