import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(raw: unknown): ValidationResult {
  if (!raw || typeof raw !== 'object') {
    return {valid: false, error: 'Message must be a JSON object'};
  }

  const message = raw as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a string "type" field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);

    case 'ping':
      return validatePingMessage(message);

    case 'list_sessions':
      return validateListSessionsMessage(message);

    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have a string "content" field'};
  }

  const trimmed = message.content.trim();
  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {
      valid: false,
      error: `Message content exceeds maximum length of ${MAX_CONTENT_LENGTH} characters`,
    };
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (!hasAcceptableLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  const cursor = parseBeforeCursor(message.before);
  if (cursor === null) {
    return {valid: false, error: 'list_sessions before must have sessionId and updatedAt'};
  }

  const frame: ListSessionsMessage = {type: 'list_sessions'};
  if (typeof message.limit === 'number') frame.limit = message.limit;
  if (cursor !== undefined) frame.before = cursor;
  return {valid: true, data: frame};
}

function hasAcceptableLimit(limit: unknown): boolean {
  if (limit === undefined) return true;
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
}

function parseBeforeCursor(before: unknown): SessionCursor | undefined | null {
  if (before === undefined) return undefined;
  if (typeof before !== 'object' || before === null) return null;

  const candidate = before as Record<string, unknown>;
  if (!hasAcceptableSessionId(candidate.sessionId)) return null;
  if (!hasAcceptableUpdatedAt(candidate.updatedAt)) return null;
  return {
    sessionId: candidate.sessionId,
    updatedAt: candidate.updatedAt,
  };
}

const MAX_SESSION_ID_LENGTH = 128;

function hasAcceptableSessionId(sessionId: unknown): sessionId is string {
  return typeof sessionId === 'string' && sessionId.length >= 1 && sessionId.length <= MAX_SESSION_ID_LENGTH;
}

function hasAcceptableUpdatedAt(updatedAt: unknown): updatedAt is string | number {
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return false;
  return Number.isFinite(new Date(updatedAt).getTime());
}

